    let edited = edit_dev_kit(path_str, &diff).unwrap();
    let persisted = import_dev_kit(path_str).unwrap();
    assert_eq!(edited.name, "Workflow Kit Edited");
    assert!(are_kits_equal(&edited, &persisted));
}

