    let mut result = Piece { guid: base.guid.clone(), ... };
    if let Some(plane_diff) = &diff.plane {
        result.plane = Some(apply_plane_diff(base.plane.as_ref().unwrap(), plane_diff));
    }
    result
}

// AFTER:
pub fn apply_piece_diff(target: &mut Piece, diff: &PieceDiff) {
    if let Some(name) = &diff.name { target.name = Some(name.clone()); }
    if let Some(plane_diff) = &diff.plane {
        if let Some(ref mut plane) = target.plane {
            apply_plane_diff(plane, plane_diff);
        }
    }
    // ... etc
}
```

**Pattern for collection diffs:**
```rust
// BEFORE:
pub fn apply_collection_diff<T, D, F>(items: &[T], diff: &CollectionDiff<T, D>, apply_fn: F) -> Vec<T>
where T: HasGuid + Clone, F: Fn(&T, &D) -> T {
    let mut result = items.to_vec();
    // ... filter, map
    result
}

// AFTER:
pub fn apply_collection_diff<T, D, F>(items: &mut Vec<T>, diff: &CollectionDiff<T, D>, apply_fn: F)
where T: HasGuid + Clone, F: Fn(&mut T, &D) {
    if let Some(removed) = &diff.removed {
        let removed_guids: HashSet<_> = removed.iter().map(|r| r.guid()).collect();
        items.retain(|item| !removed_guids.contains(item.guid()));
    }
    if let Some(updated) = &diff.updated {
        for update in updated {
            if let Some(item) = items.iter_mut().find(|i| i.guid() == update.id.guid()) {
                apply_fn(item, &update.diff);
            }
        }
    }
    if let Some(added) = &diff.added {
        items.extend(added.iter().cloned());
    }
}
